-- Generated by cargo run -p inventory-engine --example resource_views.
-- Source-specific views preserve Cloud Control fields even when direct observations win.

CREATE VIEW aws_cc_app_config_experiment_definition AS
SELECT r.*,
       json_extract(r.provider_properties, '$.ApplicationId') AS "application_id",
       json_extract(r.provider_properties, '$.ApplicationIdentifier') AS "application_identifier",
       json_extract(r.provider_properties, '$.AudienceDescription') AS "audience_description",
       json_extract(r.provider_properties, '$.AudienceRule') AS "audience_rule",
       json_extract(r.provider_properties, '$.ConfigurationProfileIdentifier') AS "configuration_profile_identifier",
       json_extract(r.provider_properties, '$.Control') AS "control",
       json_extract(r.provider_properties, '$.CreatedAt') AS "created_at",
       json_extract(r.provider_properties, '$.EnvironmentIdentifier') AS "environment_identifier",
       json_extract(r.provider_properties, '$.FlagKey') AS "flag_key",
       json_extract(r.provider_properties, '$.Hypothesis') AS "hypothesis",
       json_extract(r.provider_properties, '$.Id') AS "provider_id",
       json_extract(r.provider_properties, '$.LaunchCriteria') AS "launch_criteria",
       json_extract(r.provider_properties, '$.Name') AS "provider_name",
       json_extract(r.provider_properties, '$.Status') AS "status",
       json_extract(r.provider_properties, '$.Tags') AS "provider_tags",
       json_extract(r.provider_properties, '$.Treatments') AS "treatments",
       json_extract(r.provider_properties, '$.UpdatedAt') AS "updated_at"
FROM aws_cloudcontrol_resource r WHERE cloudformation_type = 'AWS::AppConfig::ExperimentDefinition';

CREATE VIEW aws_cc_eks_access_entry AS
SELECT r.*,
       json_extract(r.provider_properties, '$.AccessEntryArn') AS "access_entry_arn",
       json_extract(r.provider_properties, '$.AccessPolicies') AS "access_policies",
       json_extract(r.provider_properties, '$.ClusterName') AS "cluster_name",
       json_extract(r.provider_properties, '$.KubernetesGroups') AS "kubernetes_groups",
       json_extract(r.provider_properties, '$.PrincipalArn') AS "principal_arn",
       json_extract(r.provider_properties, '$.Tags') AS "provider_tags",
       json_extract(r.provider_properties, '$.Type') AS "type",
       json_extract(r.provider_properties, '$.Username') AS "username"
FROM aws_cloudcontrol_resource r WHERE cloudformation_type = 'AWS::EKS::AccessEntry';

CREATE VIEW aws_cc_eks_pod_identity_association AS
SELECT r.*,
       json_extract(r.provider_properties, '$.AssociationArn') AS "association_arn",
       json_extract(r.provider_properties, '$.AssociationId') AS "association_id",
       json_extract(r.provider_properties, '$.ClusterName') AS "cluster_name",
       json_extract(r.provider_properties, '$.DisableSessionTags') AS "disable_session_tags",
       json_extract(r.provider_properties, '$.ExternalId') AS "external_id",
       json_extract(r.provider_properties, '$.Namespace') AS "namespace",
       json_extract(r.provider_properties, '$.Policy') AS "policy",
       json_extract(r.provider_properties, '$.RoleArn') AS "role_arn",
       json_extract(r.provider_properties, '$.ServiceAccount') AS "service_account",
       json_extract(r.provider_properties, '$.Tags') AS "provider_tags",
       json_extract(r.provider_properties, '$.TargetRoleArn') AS "target_role_arn"
FROM aws_cloudcontrol_resource r WHERE cloudformation_type = 'AWS::EKS::PodIdentityAssociation';

PRAGMA user_version = 13;
